using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Extensions.Pack;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.Extensions.DependencyInjection;
using AspNetCore.MinimalApi.Sdk.CodeRules.Mediator;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Mediator")]
    [TestClass]
    public class RJIT_CR_MR_00001 : MediatorTestBase
    {
        // 1. Handler and commands and queries have to be in the same file
        // 2. Command/Queries have to use the Response type as generic parameter
        // 3. MediatR registration have to be done for each assembly in which a handler is declared.
        [TestMethod]
        public void Comand_And_Query_Class_Have_To_Be_Declared_In_Same_File_Like_The_Handler()
        {
            var separatedHandlers = (from handler in MediatorImplementations
                                     where handler.Request is null
                                     select new
                                     {
                                         Error = $@"
MediatR Handler: {handler.Handler.Name} does not have the request: '{handler.RequestType}' not defined in the same file.
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Request Type:    {handler.RequestType}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:          

public record {handler.RequestType};

{handler.Handler.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                     }).ToImmutableList();
            
            Assert.IsTrue(separatedHandlers.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_MR_00001

Query/Command handler is not in the same file as the processing part. 
For debug and maintainability aspects put the query or command into your handler
in which the processing take place. It is called F12 debug experience:{Environment.NewLine}{separatedHandlers.Select(e => e.Error).Flatten(Environment.NewLine)}");
        }
    }
}
